#include <cstdio>
#include <vector>
#include <utility>
using namespace std;

static char ibuf[1 << 16];
static int ipos = 0, ilen = 0;

inline int readChar() {
    if (ipos == ilen) {
        ilen = (int)fread(ibuf, 1, sizeof(ibuf), stdin);
        ipos = 0;
        if (ilen <= 0) return -1;
    }
    return ibuf[ipos++];
}

inline int readInt() {
    int c = readChar();
    while (c != -1 && (c < '0' || c > '9') && c != '-') c = readChar();
    if (c == -1) return -1;
    int sign = 1;
    if (c == '-') {
        sign = -1;
        c = readChar();
    }
    int x = 0;
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = readChar();
    }
    return x * sign;
}

int main() {
    int E = readInt(), M = readInt(), D = readInt();

    vector<pair<int,int>> same(M), diff(D);
    for (int i = 0; i < M; ++i) {
        int x = readInt(), y = readInt();
        same[i] = make_pair(x, y);
    }
    for (int i = 0; i < D; ++i) {
        int x = readInt(), y = readInt();
        diff[i] = make_pair(x, y);
    }

    vector<int> grp(E + 1, 0);
    int numGroups = E / 3;
    for (int g = 0; g < numGroups; ++g) {
        int a = readInt(), b = readInt(), c = readInt();
        grp[a] = g;
        grp[b] = g;
        grp[c] = g;
    }

    long long violations = 0;
    for (int i = 0; i < M; ++i) {
        if (grp[same[i].first] != grp[same[i].second]) ++violations;
    }
    for (int i = 0; i < D; ++i) {
        if (grp[diff[i].first] == grp[diff[i].second]) ++violations;
    }

    printf("%lld\n", violations);
    return 0;
}
